import SwiftUI

struct PreviewItem: Identifiable {
    let id = UUID()
    var previewImage: String
}

class PreviewItemManager {
    var items: [PreviewItem] = []

    func addItem(item: PreviewItem) {
        items.append(item)
    }

    func removeItem(at index: Int) {
        items.remove(at: index)
    }

    func previewItem(at offset: Offset, in view: AnyView) -> AnyView {
        return AnyView(
            ZStack(alignment: .center) {
                view
                HStack {
                    Spacer()
                    Image(systemName: "pencil")
                        .font(.system(size: 24))
                        .foregroundColor(.gray)
                    Spacer()
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 8)
                .background(Color.white)
                .cornerRadius(8)
            }
        )
    }
}

struct PreviewItemView: View {
    @StateObject var previewItemManager = PreviewItemManager()
    @State private var previewItem: PreviewItem? = nil

    var body: some View {
        NavigationView {
            List {
                ForEach(previewItemManager.items) { item in
                    Button(action: {
                        previewItemManager.addItem(item: item)
                    }) {
                        previewItemManager.previewItem(at: .zero, in: self)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color.white)
                    .cornerRadius(8)
                    .padding(.horizontal, 16)
                    .padding(.vertical, 8)
                    .foregroundColor(.blue)
                }
            }
            .navigationBarTitle("Preview")
        }
    }
}

struct PreviewItemView_Previews: PreviewProvider {
    static var previews: some View {
        PreviewItemView()
    }
}
```

