Title: Remix submit form onChange and get live update from useActionData().
Body: <p>I am trying to create a remix page where i want to get live preview when i change a <code>Select</code> tag. It is going through a Form since i want it to translate the data.</p>
<p>A solution to my problem could be to make <code>preventDefault</code>(first code example) to work or to find a way to make <code>useActionData()</code>(second code example) to work when using <code>useFetcher</code></p>
<p>With this code, the <code>preventDefault</code> does not work. I need <code>preventDefault</code> to work so that the selector doesn't reset. I could make the action function also send the name so that the DefaultValue in select is imported from action function, but this is going to become a big form and i dont want to refresh the whole page.</p>
<pre><code>export async function action({ request }: ActionArgs) {
    const form = new URLSearchParams(await request.text())
    const name = form.get('name');
    console.log('name', name);
    return json({ message: name ? `Hello ${name}!` : 'Select name' });
}

export default function Page() {
    const actionData = useActionData();
    console.log('actionData', actionData);

    return (
        &lt;&gt;
            &lt;Form method=&quot;post&quot;&gt;

                &lt;h1&gt;{actionData ? actionData.message : 'Select name.'}&lt;/h1&gt;

                &lt;select 
                    name=&quot;name&quot; 
                    onChange={e =&gt; {
                        e.preventDefault();
                        e.target.form.submit();
                    }}
                &gt;
                    &lt;option value=&quot;name 1&quot;&gt;Name 1&lt;/option&gt;
                    &lt;option value=&quot;name 2&quot;&gt;Name 2&lt;/option&gt;
                    &lt;option value=&quot;name 3&quot;&gt;Name 3&lt;/option&gt;
                &lt;/select&gt;

                &lt;button type=&quot;submit&quot; className=&quot;bg-blue-500 text-white font-bold py-2 px-4&quot;&gt;
                    Submit
                &lt;/button&gt;

                &lt;/Form&gt;
        &lt;/&gt;
    );
}
</code></pre>
<p>I have also tried following <a href="https://github.com/remix-run/remix/issues/1807" rel="noreferrer">https://github.com/remix-run/remix/issues/1807</a> using <code>useRef and useFetcher</code>, but even tho the action function runs, it gives me <code>undefined</code>  when logging actionData.</p>
<pre><code>export async function action({ request }: ActionArgs) {
    const form = new URLSearchParams(await request.text())
    const name = form.get('name');
    console.log('name', name);
    return json({ message: name ? `Hello ${name}!` : 'Select name' });
}

export default function Page() {
    const actionData = useActionData();
    console.log('actionData', actionData); // Gives undefined

    const formRef = useRef&lt;HTMLFormElement&gt;(null);
    const fetcher = useFetcher();

    return (
        &lt;&gt;
            &lt;fetcher.Form method=&quot;post&quot; ref={formRef}&gt;

                &lt;h1&gt;{actionData ? actionData.message : 'Select name.'}&lt;/h1&gt;

                &lt;select 
                    name=&quot;name&quot; 
                    onChange={() =&gt; {
                        fetcher.submit(formRef.current);
                    }}
                &gt;
                    &lt;option value=&quot;name 1&quot;&gt;Name 1&lt;/option&gt;
                    &lt;option value=&quot;name 2&quot;&gt;Name 2&lt;/option&gt;
                    &lt;option value=&quot;name 3&quot;&gt;Name 3&lt;/option&gt;
                &lt;/select&gt;

                &lt;button type=&quot;submit&quot; className=&quot;bg-blue-500 text-white font-bold py-2 px-4&quot;&gt;
                    Submit
                &lt;/button&gt;

            &lt;/fetcher.Form &gt;
        &lt;/&gt;
    );
}
</code></pre>

Answers:
```python
from flask import Flask, request, render_template, redirect, url_for
from flask import g, jsonify
from flask import make_template
from flask import Flask, request, render_template, redirect, url_for
from flask import request, render_template, redirect, url_for
from flask import make_template, request, render_template, redirect, url_for

# Create a Flask application
app = Flask(__name__)

# To get the live preview of the selected value
@app.route('/live-preview')
def live_preview():
    action_data = request.get_json()
    if action_data:
        name = action_data.get('name')
        print(name)
        return jsonify({'message': f'Hello {name}!'})
    else:
        return jsonify({'message': 'No data received.'})

# Define the action function
def action(request):
    # Get the form data
    form_data = request.form
    # Get the name from the form data
    name = form_data.get('name')
    print(name)
    return jsonify({'message': f'Hello {name}!'})

# To get the action data
@app.route('/action-data')
def action_data():
    return jsonify({'action_data': 'Hello from action data'})

# Define the page function
def page():
    # Get the action data
    action_data = request.args.get('action_data')
    print(action_data)
    return render_template('page.html', action_data=action_data)

# Define the fetcher function
def fetcher():
    return FlaskFetcher()

# Run the application
if __name__ == '__main__':
    app.run(debug=True)

# Define the template function
def template():
    return render_template('template.html')
```

Questions:
Title: Angular Material - Changing the density doesn&#39;t affect the html element.
Body: <p>I want to make my matInput smaller than the default size. The html looks like this:</p>
<pre><code>&lt;mat-form-field class=&quot;input-parent&quot; subscriptSizing=&quot;dynamic&quot; appearance=&quot;outline&quot; style=&quot; margin-right: 10px; font-size: 12px;&quot;&gt;
  &lt;input matInput type=&quot;text&quot; [(ngModel)]=&quot;input&quot; (keydown)=&quot;checkForSubmit($event)&quot;&gt;
&lt;/mat-form-field&gt;
</code></pre>
<p>In the scss, I followed <a href="https://stackoverflow.com/a/75284845/9749118">this</a>  answer, and added the following scss:</p>
<pre><code>.input-parent{
  @include mat.input-density(-2);
}
</code></pre>
<p>But, it doesn't affect the size of the input at all.
I also tried stuff like</p>
<p>-<code>mat.all-component-densities</code> instead of <code>mat.input-density</code></p>
<p>moving it out of the class to the main scss file</p>
<p>putting it inside body instead of .input-parent</p>
<p>setting the parent class to the parent of the <code>mat-form-field</code> instead of the direct parent of the <code>mat-input</code></p>
<p>but nothing works.
I also want to add that changing the density of a button worked, but not the density of an input.</p>
<p>Does anyone have a solution? Thanks</p>

Answers:
```python
import matplotlib.pyplot as plt

def change_input_density(html, scss):
    # Parse the HTML
    soup = BeautifulSoup(html, 'html.parser')

    # Find the mat-form-field element
    mat_field = soup.find('mat-form-field')

    # Find the input element inside the mat-form-field
    input_element = mat_field.find('input')

    # Get the style attribute of the input element
    input_style = input_element.get('style')

    # If the input style is not None, try to update it
    if input_style is not None:
        # Split the style into individual styles
        styles = input_style.split(';')

        # Iterate over each style
        for style in styles:
            # Split the style into key and value
            key, value = style.split(':')

            # If the style is related to density, update it
            if key.startswith('mat-input-density-'):
                # Update the density of the input
                input_style = style.replace(key, value, 1)
                input_element.style['mat-input-density'] = value

# Parse the SCSS code
html = """
<p>I want to make my matInput smaller than the default size. The html looks like this:</p>
<pre>
&lt;mat-form-field class=&quot;input-parent&quot; subscriptSizing=&quot;dynamic&quot; appearance=&quot;outline&quot; style=&quot; margin-right: 10px; font-size: 12px;&quot;&gt;
  &lt;input matInput type=&quot;text&quot; [(ngModel)]=&quot;input&quot; (keydown)=&quot;checkForSubmit($event)&quot;&gt;
&lt;/mat-form-field&gt;
</code>
</pre>
"""

scss = """
input-parent {
  @include mat.input-density(-2);
}

.input-parent {
  @include mat.input-density(-1);
}

button {
  @include mat.input-density(0);
}
"""

# Change the density of the input
change_input_density(html, scss)

