                  &lt;div class=&quot;row&quot;&gt;
                      &lt;label class=&quot;col-md-2 col-form-label&quot; for=&quot;basic-icon-default-fullname&quot;&gt;Validation&lt;/label&gt;
                      &lt;div class=&quot;col-md-10&quot;&gt;
                          &lt;div class=&quot;form-check mb-2&quot;&gt;
                              &lt;input class=&quot;form-check-input&quot; type=&quot;checkbox&quot; value=&quot;required&quot; id=&quot;required&quot; name=&quot;validation[]&quot; checked /&gt;
                              &lt;label class=&quot;form-check-label&quot; for=&quot;required&quot;&gt;Required&lt;/label&gt;
                          &lt;/div&gt;
                          &lt;div class=&quot;form-check mb-2&quot;&gt;
                              &lt;input class=&quot;form-check-input&quot; type=&quot;checkbox&quot; value=&quot;alpha&quot; id=&quot;alpha&quot; name=&quot;validation[]&quot; /&gt;
                              &lt;label class=&quot;form-check-label&quot; for=&quot;alpha&quot;&gt;Alphabets Only&lt;/label&gt;
                          &lt;/div&gt;
                          &lt;div class=&quot;form-check mb-2&quot;&gt;
                              &lt;input class=&quot;form-check-input&quot; type=&quot;checkbox&quot; value=&quot;/^[a-zA-Z\s]+$/&quot; id=&quot;alphaSpace&quot; name=&quot;validation[]&quot; /&gt;
                              &lt;label class=&quot;form-check-label&quot; for=&quot;alphaSpace&quot;&gt;Alphabets with Space&lt;/label&gt;
                          &lt;/div&gt;
                          &lt;div class=&quot;form-check mb-2&quot;&gt;
                              &lt;input class=&quot;form-check-input&quot; type=&quot;checkbox&quot; value=&quot;number&quot; id=&quot;number&quot; name=&quot;validation[]&quot; /&gt;
                              &lt;label class=&quot;form-check-label&quot; for=&quot;number&quot;&gt;Number Only&lt;/label&gt;
                          &lt;/div&gt;
                      &lt;/div&gt;
                  &lt;/div&gt;
              &lt;/div&gt;
              &lt;/form&gt;```
</code></pre>

Answers:
To merge the two Laravel AJAX functions into one, you can create a single function that handles both the form submission and the data processing. Here's an example of how you can do it:

```php
// app/Http/Requests/InputForm.php

namespace App\Http\Requests;

use Illuminate\Http\Request;

class InputForm extends Request
{
    public function rules()
    {
        return [
            'eventName' => 'required|image',
            'price' => 'required|number',
            'location' => 'required|string',
            'desc' => 'required|string',
            'image' => 'image|mimes:jpeg,png,jpg,gif',
        ];
    }
}
```

```php
// app/Http/Controllers/InputController.php

namespace App\Http\Controllers;

use App\Http\Requests\InputForm;
use App\Models\CustomField;
use Illuminate\Support\Facades\DB;

class InputController extends Controller
{
    public function store(InputForm $request)
    {
        $data = $request->all();

        // Insert data into database
        $data['image'] = $request->file('image');
        $data['location'] = $request->input('location');
        $data['desc'] = $request->input('desc');
        $data['price'] = $request->input('price');

        foreach ($data['customField'] as $field) {
            $customField = new CustomField();
            $customField->name = $field['customInputName'];
            $customField->inputType = $field['inputType'];
            $customField->validation = $field['validation'];
            $customField->save();
        }

        // Insert data into database
        foreach ($data['customField'] as $field) {
            $customField = new CustomField();
            $customField->name = $field['customInputName'];
            $customField->inputType = $field['inputType'];
            $customField->validation = $field['validation'];
            $customField->save();
        }

        DB::table('inputForm')->insert($data);

        return redirect()->route('inputForm')->with('success', 'Data inserted successfully.');
    }
}
```

```php
// app/Http/Controllers/InsertCustomFields.php

namespace App\Http\Controllers;

use Illuminate\Http\Request;

class InsertCustomFields extends Controller
{
    public function store(Request $request)
    {
        $data = $request->all();

        // Insert data into database
        foreach ($data['customField'] as $field) {
            $customField = new CustomField();
            $customField->name = $field['customInputName'];
            $customField->inputType = $field['inputType'];
            $customField->validation = $field['validation'];
            $customField->save();
        }

        return redirect()->route('inputForm')->with('success', 'Custom fields inserted successfully.');
    }
}
```

Then, you can create a single route that handles both the form submission and the data processing:

```php
// app/Http/Controllers/InputController.php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Http\Requests\InputForm;
use App\Models\CustomField;

class InputController extends Controller
{
    public function store(Request $request)
    {
        $data = $request->all();

        // Insert data into database
        $data['image'] = $request->file('image');
        $data['location'] = $request->input('location');
        $data['desc'] = $request->input('desc');
        $data['price'] = $request->input('price');

        foreach ($data['customField'] as $field) {
            $customField = new CustomField();
            $customField->name = $field['customInputName'];
            $customField->inputType = $field['inputType'];
            $customField->validation = $field['validation'];
            $customField->save();
        }

        DB::table('inputForm')->insert($data);

        return redirect()->route('inputForm')->with('success', 'Data inserted successfully.');
    }
}
```

This will merge the two Laravel AJAX functions into one and insert the data into the database.

