class clsWarehouseSum:
    def __init__(self):
        self.wh_units = {}

    def availableUnits(self, warehouse):
        if warehouse in self.wh_units:
            return self.wh_units[warehouse]
        else:
            SQL = "SELECT sum(units) as tot_units FROM warehouse WHERE warehouse = '{}'".format(warehouse)
            self.wh_units[warehouse] = self.execute_query(SQL)
            return self.wh_units[warehouse]

    def execute_query(self, SQL):
        RS = self.current_db.OpenRecordset(SQL)
        RS.Fields = ['tot_units']
        RS.MoveFirst()
        RS.MoveNext()
        return RS('tot_units')


# Usage
warehouse_sum = clsWarehouseSum()
warehouse_sum.availableUnits('Cohasset')
warehouse_sum.availableUnits('Cohasset')
```

Questions:
Title: Why map literals in Go allow overwriting keys when using a function call instead of a literal?.
Body: <pre><code>package main

import &quot;fmt&quot;

func main() {
    blaa := map[string]string{
        &quot;key&quot;:    &quot;value&quot;,
        getKey(): &quot;value2&quot;, //replacing getKey() with &quot;key&quot; results in compile time error.
    }
    fmt.Println(&quot;Hello, &quot; + blaa[&quot;key&quot;])
}

func getKey() string {
    return &quot;key&quot;
}
</code></pre>
<p>Running the above program will print &quot;Hello, value2&quot;. Try it here <a href="https://go.dev/play/p/s92LaaNc3n4" rel="nofollow noreferrer">https://go.dev/play/p/s92LaaNc3n4</a></p>
<p>While I can see the key gets overwritten, I'm wondering why this doesn't <code>panic</code> at runtime? Using two string literals <code>&quot;key&quot;</code> will result in a compilation time error, which is the expected behaviour.</p>

Answers:
```go
package main

import "fmt"

// Map literal allows overwriting keys when using a function call instead of a literal
func main() {
    blaa := map[string]string{
        "key":    "value",
        getKey:    "value2",
    }
    fmt.Println("Hello, " + blaa["key"])
}

// getKey is a function that returns a string, but when called directly, it overwrites the map
func getKey() string {
    return "key"
}
```

```python
class OrderedDictionary:
    def __init__(self):
        self.ordered_dict = {}

    def add(self, key, value):
        if key not in self.ordered_dict:
            self.ordered_dict[key] = value
        else:
            self.ordered_dict[key] = self.ordered_dict[key] + (value,)

def create_ordered_dict():
    return OrderedDictionary()

d = create_ordered_dict()
for i in range(1, 11):
    d.add(i, i + 9)
print(d.ordered_dict)
```

