import org.junit.Test;
import org.junit.runner.RunWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.junit4.SpringRunner;
import org.springframework.test.web.servlet.MockMvc;

@RunWith(SpringRunner.class)
@SpringBootTest
@AutoConfigureMockMvc
public class OIDCInitFlowEndpointTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void testRedirectUrl() {
        // Set up the request parameters
        String initFlowRequestParams = "scope=openid&response_type=id_token&response_mode=form_post&prompt=none&client_id=toolid&redirect_uri=https://localhost:8080/tool/token/receiver&login_hint=loginHint&state=1d73c90f-fe03-47dc-9e28-ed416fad7773&nonce=7b5e7240-161e-4d78-8e32-54923c9ce04a";

        // Set up the request
        mockMvc.perform(get(OIDC_INIT_FLOW_ENDPOINT)
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .params(initFlowRequestParams))
                // Verify the location header contains all required parameters
                .andExpect(status().isFound())
                .andExpect(header().exists(LOCATION))
                .andExpect(header().string(LOCATION, contains("openId")));
    }
}
```

