      actionCodeSettings: acs,
    );

    Future.delayed(const Duration(seconds: 3)).then((_) {
      _signup();
    });

    return;
  }

  @override
  void initState() {
    super.initState();
    _signup();
  }

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      home: Scaffold(
        body: Center(
          child: Text('Hello World!'),
        ),
      ),
    );
  }
}

class MainApp extends StatefulWidget {
  const MainApp({super.key});

  @override
  State&lt;MainApp&gt; widgetState;

  void _signup() async {
    final Future<void> _signup = FirebaseAuth.instance.signUp();

    Future.delayed(const Duration(seconds: 3)).then((_) {
      _signup();
    });

    return null;
  }

  @override
  void initState() {
    super.initState();
    _signup();
  }

  @override
  Widget build(BuildContext context) {
    return const MainApp();
  }
}

Questions:
Title: Next Auth google OAuth with custom backend&#39;s access token and refresh token.
Body: <p>I have a NestJS backend that exposes the following API:</p>
<pre><code>   @Post('sign-in-with-google-account')
   async signInWithGoogleAccount(
     @Body body: { idToken: string }, 
     @Res({ passthrough: true }) response: Response
   ) {
     const user = await getUserFromGoogleIdToken(body.idToken)
     const tokens = await generateAccessAndRefreshTokensForUser(user)

     response.cookie('refreshToken', tokens.refreshToken, {
         httpOnly: true,
         expires: new Date(tokenExpirationDate),
         secure: true,
         sameSite: 'none'
     })

     return { accessToken: tokens.accessToken }
   }
</code></pre>
<p>It receives id token from google oauth, finds the user in the DB and signs a JWT access token and refresh token. The refresh token is stored as <code>httpOnly</code> cookie and the access token is returned.</p>
<p>Now in my next.js app configured with <code>next-auth</code> I have the following:</p>
<pre><code>import GoogleProvider from &quot;next-auth/providers/google&quot;;

...
providers: [
  GoogleProvider({
    clientId: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET
  })
]
...

</code></pre>
<p>The problem is that <code>next-auth</code> generates its own tokens. But I want <code>next-auth</code> to use my own access and refresh tokens from the NestJS backend, how can I do that?</p>
<p>Also, In NestJS I have a API to refresh the access token like so:</p>
<pre><code>@Get('refresh-access-token')
async refreshAccessToken(@Req() request: Request) {
  const accessToken = await getNewAccessTokenFromRefreshToken(request.cookies.refreshToken)
  return { accessToken } 
}
</code></pre>
<p>How can I tell <code>next-auth</code> to refresh the access token using <code>refresh-access-token</code> API every 10 minutes (the access token expiration date)?</p>

Answers:
import { NextAuth } from 'next-auth';
import GoogleProvider from 'next-auth/providers/google';
import { refreshAccessToken } from './refresh-access-token';

const customAuthOptions = {
  // Add your NestJS API URL here
  api: {
    clientId: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET,
  },
};

const customRefreshOptions = {
  // Add your NestJS API URL here
  refreshToken: process.env.GOOGLE_CLIENT_ID + '_refresh_token',
  tokenExpirationDate: new Date('2024-12-31T23:59:59.999Z'), // Set your token expiration date
};

const authOptions = {
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
  ],
  callbacks: {
    async jwt(token, user, account, profile, options) {
      // Use your custom user data here
      user.email = account.email;
      return token;
    },
    async session(session, token, account, profile, options) {
      // Use your custom session data here
      session.user.email = account.email;
      return session;
    },
  },
  session: {
    // Use your custom session data here
    secret: process.env.SECRET_KEY,
  },
  callbacks: {
    async refresh(token, user, account, profile, options) {
      // Use your custom refresh token callback here
      const newAccessToken = await refreshAccessToken(token.refreshToken);
      return newAccessToken;
    },
  },
  // Add your custom authentication options here
};

export default NextAuth(authOptions, customAuthOptions, customRefreshOptions);

import os

def get_auth_header():
    return f"Bearer {os.environ.get('BITBUCKET_TOKEN', '')}"

def set_auth_header(header):
    os.environ['BITBUCKET_TOKEN'] = header

def get_auth_header_from_git_config():
    return os.environ.get('BITBUCKET_TOKEN', '')

def set_auth_header_from_git_config(header):
    os.environ['BITBUCKET_TOKEN'] = header

def main():
    # Using HTTP Extra Header
    set_auth_header(get_auth_header())
    print(get_auth_header())

    # Using HTTP Extra Header with GIT_AUTHORIZATION_HEADER
    set_auth_header_from_git_config(get_auth_header_from_git_config())
    print(get_auth_header_from_git_config())

if __name__ == "__main__":
    main()

