Title: Black square renders instead of an OpenCV image.
Body: <p>I'm trying to render two images of size 256x256 with ushort data type. One must be in greyscale and another in RGB. However, both render as black squares. I believe that the fault lies somewhere in my openGL texture definition, but I'm not sure.</p>
<p>Here's my minimal version of the code.</p>
<pre><code>#include &quot;imgui.h&quot;
#include &quot;imgui_impl_glfw.h&quot;
#include &quot;imgui_impl_opengl3.h&quot;
#include &lt;glad/glad.h&gt;    
#include &lt;GLFW/glfw3.h&gt;
#include &lt;opencv2/opencv.hpp&gt;

using namespace cv;


int main()
{
    //init glfw, window, glad, imgui
    glfwInit();
    const char* glsl_version = &quot;#version 330 core&quot;;
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
    GLFWwindow* window = glfwCreateWindow(600, 400, &quot;test&quot;, NULL, NULL);
    glfwMakeContextCurrent(window);
    gladLoadGL();
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    ImGui::CreateContext();
    ImGui::StyleColorsDark();
    ImGui_ImplGlfw_InitForOpenGL(window, true);
    ImGui_ImplOpenGL3_Init(glsl_version);


    //define image data
