def find_closest_points(img):
    # Get image dimensions
    height, width = img.shape[:2]

    # Find the first non-black pixel closest to the left-down and right-up corners
    nonempty = []
    for i in range(height):
        for j in range(width):
            # Check if the current pixel is non-black
            if not CheckForLess(img[i, j], 10):
                nonempty.append([i, 1080 - j])

    # Find the closest points
    closest_points = min(nonempty, key=lambda x: ((x[0] - width // 2) ** 2 + (x[1] - height // 2) ** 2) ** 0.5)

    return closest_points

def CheckForLess(list1, val):
    return all(x &lt; val for x in list1)

img = cv2.imread('enter image description here', cv2.IMREAD_GRAYSCALE)

closest_points = find_closest_points(img)
print(closest_points)

```csharp
using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class TimeoutHandler : HttpClientHandler
{
    private readonly TimeSpan connectionTimeout;
    private readonly TimeSpan responseTimeout;

    public TimeoutHandler(TimeSpan connectionTimeout, TimeSpan responseTimeout)
    {
        this.connectionTimeout = connectionTimeout;
        this.responseTimeout = responseTimeout;
    }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        try
        {
            await base.SendAsync(request, cancellationToken);
        }
        catch (OperationCanceledException)
        {
            if (responseTimeout <= connectionTimeout)
            {
                await Task.Delay(connectionTimeout, cancellationToken).Wait();
                return await base.SendAsync(request, cancellationToken);
            }
        }

        return await base.SendAsync(request, cancellationToken);
    }
}
