Answers:
To solve the problem, you need to add error handling for the `reqwest` client. The issue arises because `reqwest` does not handle errors properly. When a request fails, it returns an error immediately without waiting for the response. 

You can use `reqwest::Error::from()` to create a new error instance that wraps the original error. Here's how you can modify your code:

```rust
use reqwest::Error as ReqwestError;
use hyper::Error as HyperError;

// ...

pub async fn send_message_to_extractor(
    message: DiscordMessage,
    client: &reqwest::Client,
) -> Result<_, ReqwestError> {
    // ...
    match request {
        Ok(_) => Ok(()),
        Err(e) => Err(e),
    }
}

pub async fn handle_discord_message(pool: Extension<SqlitePool>, Json(payload): Json<DiscordMessage>) -> Result<_, HyperError> {
    // ...
    // Parsing message about ~400ms of work
    // ...

    let reqwest_client = reqwest::Client::builder()
        .pool_max_idle_per_host(0)
        .build()?;
    while let Some(row) = stream.try_next().await? {
        let data: Vec<u8> = row.try_get("data")?;
        // turn data to string
        let data_string = if COMPRESSION {
            decode_reader(data)?
        } else {
            String::from_utf8(data)?
        };
        // turn string to discord message
        let discord_message: DiscordMessage = serde_json::from_str(&data_string)?;
        // send message to extractor
        //println!(&quot;sending message to extractor: {:?}&quot;, discord_message);
        send_message_to_extractor(
            discord_message,
            &reqwest_client
        )
        .await
        .map_err(|e| e.into())?;
        bar.inc(1);
        // Do something with the data vector...
    }

    Ok(())
}

pub async fn handle_discord_message_pool(pool: Extension<SqlitePool>, Json(payload): Json<DiscordMessage>) -> Result<_, HyperError> {
    // ...
    // Parsing message about ~400ms of work
    // ...

    let reqwest_client = reqwest::Client::builder()
        .pool_max_idle_per_host(0)
        .build()?;
    while let Some(row) = stream.try_next().await? {
        let data: Vec<u8> = row.try_get("data")?;
        // turn data to string
        let data_string = if COMPRESSION {
            decode_reader(data)?
        } else {
            String::from_utf8(data)?
        };
        // turn string to discord message
        let discord_message: DiscordMessage = serde_json::from_str(&data_string)?;
        // send message to extractor
        //println!(&quot;sending message to extractor: {:?}&quot;, discord_message);
        send_message_to_extractor(
            discord_message,
            &reqwest_client
        )
        .await
        .map_err(|e| e.into())?;
        bar.inc(1);
        // Do something with the data vector...
    }

    Ok(())
}
```

In the above code, I have wrapped the `reqwest::Client::post()` call in a `Result` with a custom error type `ReqwestError`. This allows you to handle errors in a more robust way.

