        System.out.println(&quot;BodyOut &quot; + envelope.bodyOut.toString());

        androidHttpTransport.debug = true;
        androidHttpTransport.call(SOAP_ACTION, envelope);

        SoapPrimitive response = (SoapPrimitive)envelope.getResponse();
        System.out.println(&quot;ResponseMessage&quot; +  response.toString());
        responseMsg = String.valueOf(response);
        System.out.println(&quot;ResponseMessage&quot; +  response.toString());
</code></pre>
<pre><code> public static Element[] getHeaderElement() {
        // create header
        Element[] header = new Element[1];
        header[0] = new Element().createElement(&quot;http://docs.oasis-open.org/wss/2004/01/oasis- 200401-wss-wssecurity-secext-1.0.xsd&quot;,&quot;Security&quot;);
        header[0].setAttribute(null, &quot;mustUnderstand&quot;,&quot;1&quot;);

        //username
        Element username = new Element().createElement(null, USER_NAME);
        username.addChild(Node.IGNORABLE_WHITESPACE,&quot;CBROWN&quot;);
        header[0].addChild(Node.ELEMENT, username);

        //password
        Element pass = new Element().createElement(null,PASSWORD);
        pass.setAttribute(null, &quot;Type&quot;, &quot;http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText&quot;);
//        pass.addChild(Node.TEXT, PASSWORD);
        username.addChild(Node.ELEMENT, pass);

        return header;
    }
}
</code></pre>

Title: How to create endpoint with different response content types depending on accept header in Java with Micronaut.
Body: <p>I am having a play with Micronaut, and want to create an endpoint that returns either <code>text/plain</code> or <code>text/html</code>, depending on the Accept header in the request.</p>
<p>I found two ways to do this:</p>
<ol>
<li>create two methods for the same endpoint with different <em>produces</em> attributes,</li>
<li>handle it all in a single method and that evaluates the accept header and use logic in my own code to return the right content type.</li>
</ol>
<p>I like the first way best, because it's very clean, and requires no logic from me:</p>
<pre><code>    @Get(uri=&quot;/&quot;, produces=&quot;text/html&quot;)
    public String indexHtml() {
        return &quot;&quot;&quot;
            &lt;html&gt;&lt;head&gt;&lt;meta charset=\&quot;utf-8\&quot;&gt;&lt;/head&gt;
            &lt;body&gt;
            &lt;h1&gt;Demo service&lt;/h1&gt;
            &lt;/body&gt;&lt;/html&gt;&quot;&quot;&quot;;
    }
    @Get(uri=&quot;/&quot;, produces=&quot;text/plain&quot;)
    public String indexText() {
        return &quot;Demo service\r\n&quot;;
    }

</code></pre>
<p>This works well when an accept header is in the request. However, when there is no accept header, I get an error response <code>400 Bad Request</code> with a message <code>&quot;More than 1 route matched the incoming request. The following routes matched /demo: GET - /demo, GET - /demo&quot;</code></p>
<p><strong>Question 1</strong>
Is there a way to provide a 3rd endpoint as a fallback, or to designate one of these methods as the default?</p>
<p>The second way to do it, resulted in a method that I don't find very elegant:</p>
<pre><code>    @Get(uri=&quot;/&quot;, produces={MediaType.TEXT_PLAIN, MediaType.TEXT_HTML})
    public String index(HttpRequest&lt;?&gt; request) {
        Collection&lt;MediaType&gt; mediaTypes = request.accept();
        Iterator&lt;MediaType&gt; it = mediaTypes.iterator();
        if (it.hasNext()) {
            MediaType mediaType = it.next();
            if (MediaType.TEXT_PLAIN_TYPE.equals(mediaType))
                    return &quot;Demo service\r\n&quot;;
            if (MediaType.TEXT_HTML_TYPE.equals(mediaType))
                    return &quot;&quot;&quot;
                        &lt;!DOCTYPE html&gt;
                        &lt;html&gt;&lt;head&gt;&lt;meta charset=\&quot;utf-8\&quot;&gt;&lt;/head&gt;
                        &lt;body&gt;
                        &lt;h1&gt;Demo service&lt;/h1&gt;
                        &lt;/body&gt;&lt;/html&gt;&quot;&quot;&quot;;
        }
        return &quot;&quot;&quot;
            {
                &quot;title&quot;: &quot;Demo service&quot;,
            }&quot;&quot;&quot;;
    }
</code></pre>
<p><strong>Question 2</strong></p>
<ul>
<li>If it's really necessary to handle this in a single method, is it indeed done by fetching the accept header and evaluating that, or should it be done differently?</li>
</ul>

Answers:
```java
import io.micronaut.http.MediaType;
import io.micronaut.http.annotation.Get;
import io.micronaut.http.annotation.Produces;

@Get(uri = "/demo", produces = {MediaType.TEXT_PLAIN, MediaType.TEXT_HTML})
public class DemoService {

    @Produces(MediaType.TEXT_PLAIN)
    public String indexText() {
        return "Demo service\r\n";
    }

    @Produces(MediaType.TEXT_HTML)
    public String indexHtml() {
        return "<html><head><meta charset=\"utf-8\"></head><body><h1>Demo service</h1></body></html>";
    }

    @Produces
    public String index() {
        String accept = request.accept();
        if (accept == null || accept.startsWith("text/plain")) {
            return "Demo service\r\n";
        } else if (accept.startsWith("text/html")) {
            return "<html><head><meta charset=\"utf-8\"></head><body><h1>Demo service</h1></body></html>";
        } else {
            return "Invalid content type";
        }
    }
}
```

