Title: How to customize JAX-WS RuntimeException responses?.
Body: <p>I am trying to customize the fault responses for <code>RuntimeException</code>s thrown before reaching to the <code>WebMethod</code>, like invalid xml body or wrong method name  for a JAX-WS service.
I tried to use a handler with <code>@HandlerChain</code> but the response is sent before processed by the handler.</p>
<p>Here is an example. Lets say i have a method copyTool method in my ws but client sent below request. I want to be able to customize the response so that i can change the faultString or return some custom faultCode.</p>
<p><strong>Input</strong></p>
<pre><code>&lt;soapenv:Envelope xmlns:soapenv=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;
xmlns:cor=&quot;http://acme.com/&quot;&gt;
   &lt;soapenv:Header/&gt;
   &lt;soapenv:Body&gt;
      &lt;cor:copyTool&gt;
       &lt;toolNumber&gt;some Text instead of Integer&lt;/toolNumber&gt;
      &lt;/cor:copyTool&gt;
   &lt;/soapenv:Body&gt;
&lt;/soapenv:Envelope&gt;
</code></pre>
<p><strong>Output</strong></p>
<pre><code>    &lt;S:Envelope xmlns:S=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;&gt;
   &lt;S:Body&gt;
      &lt;ns0:Fault xmlns:ns0=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot; xmlns:ns1=&quot;http://www.w3.org/2003/05/soap-envelope&quot;&gt;
         &lt;faultcode&gt;ns0:Server&lt;/faultcode&gt;
         &lt;faultstring&gt;Exception Description: The object [some Text instead of Integer], of class [class java.lang.String], from mapping [org.eclipse.persistence.oxm.mappings.XMLDirectMapping[toolNumber--&gt;toolNumber/text()]] with descriptor [XMLDescriptor(com.acme --&gt; [DatabaseTable(ns0:copyTool)])], could not be converted to [class java.lang.Integer].
Internal Exception: java.lang.NumberFormatException: For input string: &quot;some Text instead of Integer&quot;&lt;/faultstring&gt;
      &lt;/ns0:Fault&gt;
   &lt;/S:Body&gt;
&lt;/S:Envelope&gt;
</code></pre>

Answers:
from jax import HTTP
from jax import HTTPException
from jax import types

def handler_chain(*args, **kwargs):
    def custom_handler_chain(*args, **kwargs):
        # Get the fault information
        fault = kwargs['fault']
        fault_code = fault['faultcode']
        fault_string = fault['faultstring']

        # Return a custom response
        return {'status': 'OK', 'message': 'Tool number {} is valid'.format(fault_code), 'faultString': fault_string}

    return types.HandlerChain(handler_chain)

def custom_ws_handler(*args, **kwargs):
    try:
        # Call the original handler
        result = super().call(*args, **kwargs)

        # If a fault occurs, return a custom response
        if isinstance(result, HTTPException):
            return {'status': 'OK', 'message': 'Fault handled', 'faultString': result.description}

        # If no fault occurs, return the original response
        return {'status': 'OK', 'message': 'Fault handled', 'faultString': 'No fault occurred'}

    except Exception as e:
        # Return a custom response for any other error
        return {'status': 'OK', 'message': 'Error handling fault', 'faultString': str(e)}

def custom_ws_service(*args, **kwargs):
    # Call the custom handler
    return custom_ws_handler(*args, **kwargs)

# Test the custom handler
def copyTool(*args, **kwargs):
    try:
        # Call the original method
        return super().copyTool(*args, **kwargs)

    except Exception as e:
        # Return a custom response for any other error
        return {'status': 'OK', 'message': 'Error calling method', 'faultString': str(e)}

# Test the custom handler with a valid request
result = custom_ws_service(copyTool, '123', '1234')
print(result)

# Test the custom handler with an invalid request
result = custom_ws_service(copyTool, '123', 'abc')
print(result)

```java
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public class Main {

    public static void main(String[] args) {
        // Read the WSDL file
        File wsdlFile = new File("path_to_your_wsdl_file.wsdl");
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(wsdlFile);

        // Generate stubs using Gradle 7.6
        generateStubs(document, wsdlFile);
    }

    private static void generateStubs(Document document, File wsdlFile) {
        try {
            // Get the WSDL file contents
            String wsdlContents = document.getDocumentElement().getTextContent();

            // Read the WSDL file
            File wsdlFileContent = new File(wsdlFile);
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(wsdlFileContent);

            // Get the stub classes
            NodeList stubClasses = document.getElementsByTagName("Stub");

            // Create the stub classes directory
            File stubClassesDir = new File("build/generated/java/stubs");
            stubClassesDir.mkdir();

            // Iterate over each stub class
            for (int i = 0; i < stubClasses.getLength(); i++) {
                Element stubClass = (Element) stubClasses.item(i);

                // Get the class name
                String className = stubClass.getAttribute("name");

                // Generate the Java class file
                File javaFile = new File(stubClassesDir, className + ".java");
                javaFile.writeText(wsdlContents);
            }
        } catch (ParserConfigurationException | SAXException | IOException e) {
            System.out.println("Error generating stubs: " + e.getMessage());
        }
    }
}
```

