```csharp
using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class MyDbContext : DbContext
{
    public DbSet<MyTable> MyTable { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseSqlServer("Server=10.0.1.1;Database=mydb;User Id=myuser;Password=mypassword;");
    }
}

public class MyTable
{
    public Guid Ticket { get; set; }
    public int UserID { get; set; }
    public int Progress { get; set; }
    public DateTime Created { get; set; }
    public int KeepRes { get; set; }
    public string Result { get; set; }
    public DateTime? ResultFetched { get; set; }
    public string CorrelationID { get; set; }

    public MyTable()
    {
    }

    public MyTable(int ticket, int user_id, int progress, DateTime created, int keep_res, string result, DateTime? result_fetched, string correlation_id)
    {
        Ticket = ticket;
        UserID = user_id;
        Progress = progress;
        Created = created;
        KeepRes = keep_res;
        Result = result;
        ResultFetched = result_fetched;
        CorrelationID = correlation_id;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        using (var context = new MyDbContext())
        {
            await context.MyTable.FindAsync(new Guid("some_ticket"));
        }
    }
}
