import * as dtrace from 'dtrace';
import * as dynamic from 'dynamic';

// Set up the tracing agent
dtrace.start("System.Private.CoreLib");

// Define a function to measure the time it takes to call System.Reflection.Emit.DynamicMethod.CreateDelegate
function measureDynamicMethodCreateDelegateTime() {
    const startTime = performance.now();
    dynamic.CreateDelegate.call(this, null);
    const endTime = performance.now();
    return endTime - startTime;
}

// Define a function to measure the time it takes to call System.Runtime.Loader.AssemblyLoadContext.LoadFromAssemblyPath
function measureAssemblyLoadTime() {
    const startTime = performance.now();
    dynamic.LoadFromAssemblyPath.call(null, null);
    const endTime = performance.now();
    return endTime - startTime;
}

// Define a function to measure the time it takes to call System.Threading.LowLevelLifoSemaphore.WaitForSignal
function measureLowLevelLifoSemaphoreWaitTime() {
    const startTime = performance.now();
    dynamic.WaitForSignal.call(null, null);
    const endTime = performance.now();
    return endTime - startTime;
}

// Define a function to measure the time it takes to call System.Reflection.Emit.DynamicMethod.CreateDelegate and System.Runtime.Loader.AssemblyLoadContext.LoadFromAssemblyPath
function measureDynamicMethodAndAssemblyLoadTime() {
    const startTime = performance.now();
    dynamic.CreateDelegate.call(null, null);
    dynamic.LoadFromAssemblyPath.call(null, null);
    const endTime = performance.now();
    return endTime - startTime;
}

// Measure the time it takes to call each function and print the results
dtrace.start("System.Private.CoreLib");
console.log("Measure DynamicMethodCreateDelegate time:", measureDynamicMethodCreateDelegateTime());
console.log("Measure AssemblyLoadTime:", measureAssemblyLoadTime());
console.log("Measure LowLevelLifoSemaphoreWaitTime:", measureLowLevelLifoSemaphoreWaitTime());
console.log("Measure DynamicMethodAndAssemblyLoadTime:", measureDynamicMethodAndAssemblyLoadTime());
dtrace.stop("System.Private.CoreLib");
```

Questions:
Title: Diff values file using helm provider.
Body: <p>I hope you can help me light some more light on my issue.</p>
<p>Currently I'm using:</p>
<ul>
<li>Terraform v1.3.5</li>
<li>Helm provider v2.8.0</li>
<li>Kubernetes provider v2.16.1</li>
</ul>
<p>Lately I've been adapting the helm provider on Terraform, to help me manage Helm releases with more resiliency. It helps a lot to be able to <code>plan</code> changes and see what has changed and what remains the same. It merges really well with the infrastructure details and I can manage everything with just one tool, it has been great.</p>
<p>There is one thing that bothers me a little. It's the <code>terraform plan</code> preview of the values file, it just shows you that some changes have been made, but not where or which. Let me add an example.</p>
<p>File <code>main.tf</code>:</p>
<pre><code># I'm using the &quot;manifest&quot; setting to calculate manifest diffs
provider &quot;helm&quot; {
  kubernetes {
    config_path    = &quot;~/.kube/config&quot;
    config_context = &quot;clusterconfig&quot;
  }
  experiments {
    manifest = true
  }
}

# The helm chart lives locally on my repo. I'm passing the values file and an
#  override for the image tag.
resource &quot;helm_release&quot; &quot;release&quot; {
  name      = &quot;example&quot;
  chart     = &quot;../../helm/chart&quot;
  namespace = &quot;example&quot;
  wait      = true
  set {
    name  = &quot;image.tag&quot;
    value = &quot;latest&quot;
  }
  values = [
    file(&quot;helm/values-example.yaml&quot;)
  ]
}
</code></pre>
<p>This works great, the problem comes when I make a change on the values file. It shows the whole file instead of just the changes. For example in my values file I change the replicas from 1 to 2:</p>
<p>File <code>values-example.yaml</code>:</p>
<pre class="lang-yaml prettyprint-override"><code>replicaCount: 1
image:
  repository: test
  pullPolicy: ifNotPresent
</code></pre>
<p>The execution:</p>
<pre class="lang-bash prettyprint-override"><code>$ terraform plan
(...)
Terraform will perform the following actions:

  # helm_release.example will be updated in-place
  ~ resource &quot;helm_release&quot; &quot;example&quot; {
      ~ manifest       = jsonencode(
          ~ {
              ~ &quot;deployment.apps/apps/v1/deployname&quot;      = {
                  ~ spec       = {
                      - replicas = 1 -&gt; 2
                        }
                    }
                }
            }
        )
  ~ values                     = [
    - &lt;&lt;-EOT
    replicaCount: 1
    image:
      repository: test
      pullPolicy: ifNotPresent
    EOT,
    + &lt;&lt;-EOT
    replicaCount: 2
    image:
      repository: test
      pullPolicy: ifNotPresent
    EOT,
  ]
</code></pre>
<p>This makes it very difficult to see which values settings have been changed, when the values file is bigger.</p>
<p><strong>So then, my question</strong>, do you know if there is a way to diff the values? I would like to see only the changes instead of the whole file.</p>
<p>What I've seen online:</p>
<ul>
<li>It's been asked for on GitHub, but closed <a href="https://github.com/hashicorp/terraform-provider-helm/issues/305" rel="noreferrer">https://github.com/hashicorp/terraform-provider-helm/issues/305</a></li>
<li>Maybe something like this can be implemented: <a href="https://stackoverflow.com/questions/66259007/use-diferent-values-in-helm-deploy-through-terraform-for-each?newreg=10e2602409f1472abf1bfc560c39986c">Use diferent values in helm deploy through Terraform (for_each)</a></li>
</ul>
<p>Thanks in advance for the help. Let me know if I can help with any more information.</p>

Answers:
import json
import os

def get_values_diff(values_file):
    # Read the values file
    with open(values_file, 'r') as f:
        values = json.load(f)

    # Initialize the diff object
    diff = []

    # Iterate over the values
    for key, value in values.items():
        # If the value is a dictionary, recursively call the function
        if isinstance(value, dict):
            diff.append(get_values_diff(value['file']))
        # If the value is not a dictionary, check if it has changed
        else:
            if value != os.path.getmtime(values_file):
                diff.append(f'{key}: changed from {os.path.getmtime(values_file)} to {value["file"]}')

    # Sort the diff
    diff.sort()

    # Print the diff
    for line in diff:
        print(line)

main.tf:
    # I'm using the &quot;manifest&quot; setting to calculate manifest diffs
    provider 'helm' {
      kubernetes {
        config_path    = '~/.kube/config'
        config_context = 'clusterconfig'
      }
      experiments {
        manifest = true
      }
}

# The helm chart lives locally on my repo. I'm passing the values file and an
#  override for the image tag.
resource 'helm_release' 'example' {
  name      = 'example'
  chart     = '../../helm/chart'
  namespace = 'example'
  wait      = true
  set {
    name  = 'image.tag'
    value = 'latest'
  }
  values = [
    file('helm/values-example.yaml')
  ]
}

import paramiko

def check_remote_host_identification():
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    try:
        ssh.connect('github.com', username='your_username', password='your_password')
    except paramiko.AuthenticationException:
        print("Authentication failed. Please check your credentials.")
    except paramiko.SSHException as e:
        print(f"SSH connection failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

    if ssh.get_host_key():
        print("Remote host identification has changed. Consider using SSH key authentication instead.")
    else:
        print("No remote host identification change detected. You can consider using SSH key authentication.")

check_remote_host_identification()

